CREATE OR REPLACE FUNCTION "public"."check_refill_pipeline_health"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_overdue_pending integer;
  v_stale_routing integer;
  v_failed_24h integer;
  v_success_24h integer;
BEGIN
  SELECT count(*) INTO v_overdue_pending
  FROM public.topup_executions
  WHERE status = 'pending' AND execution_time < now() - interval '2 hours';

  SELECT count(*) INTO v_stale_routing
  FROM public.topup_executions
  WHERE status = 'routing' AND created_at < now() - interval '30 minutes';

  IF v_overdue_pending > 0 OR v_stale_routing > 0 THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.system_alerts
      WHERE kind = 'refill_queue_backed_up' AND created_at > now() - interval '6 hours'
    ) THEN
      INSERT INTO public.system_alerts (kind, message, details)
      VALUES (
        'refill_queue_backed_up',
        'Refill queue is backing up: ' || v_overdue_pending || ' pending execution(s) overdue by 2h+, '
          || v_stale_routing || ' routing execution(s) unclaimed for 30m+. Are the PM2 workers running?',
        jsonb_build_object('overdue_pending', v_overdue_pending, 'stale_routing', v_stale_routing)
      );
    END IF;
  END IF;

  SELECT count(*) FILTER (WHERE status = 'failed'),
         count(*) FILTER (WHERE status = 'success')
  INTO v_failed_24h, v_success_24h
  FROM public.topup_executions
  WHERE COALESCE(completed_at, executed_at) > now() - interval '24 hours';

  IF v_failed_24h > 0 AND v_success_24h = 0 THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.system_alerts
      WHERE kind = 'refill_zero_success' AND created_at > now() - interval '6 hours'
    ) THEN
      INSERT INTO public.system_alerts (kind, message, details)
      VALUES (
        'refill_zero_success',
        'Every refill execution in the last 24h failed (' || v_failed_24h || ' failure(s), 0 successes).',
        jsonb_build_object('failed_24h', v_failed_24h, 'success_24h', v_success_24h)
      );
    END IF;
  END IF;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."credit_wallet"("p_user_id" "uuid", "p_amount" numeric, "p_type" "text" DEFAULT 'deposit'::"text", "p_description" "text" DEFAULT 'Wallet deposit'::"text", "p_reference_id" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_wallet_id UUID;
  v_balance_before NUMERIC;
  v_balance_after NUMERIC;
  v_txn_id UUID;
BEGIN
  SELECT id, balance INTO v_wallet_id, v_balance_before
  FROM public.wallets
  WHERE user_id = p_user_id
  FOR UPDATE;

  IF v_wallet_id IS NULL THEN
    RAISE EXCEPTION 'Wallet not found for user %', p_user_id;
  END IF;

  v_balance_after := v_balance_before + p_amount;

  UPDATE public.wallets
  SET balance = v_balance_after,
      total_deposited = total_deposited + p_amount
  WHERE id = v_wallet_id;

  INSERT INTO public.wallet_transactions (
    wallet_id, user_id, type, amount, balance_before, balance_after,
    description, reference_id, status
  ) VALUES (
    v_wallet_id, p_user_id, p_type, p_amount, v_balance_before, v_balance_after,
    p_description, p_reference_id, 'completed'
  ) RETURNING id INTO v_txn_id;

  RETURN v_txn_id;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."handle_new_household_member"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Auto-populate member_id if a profile with member_email exists
  SELECT id INTO NEW.member_id
  FROM public.profiles
  WHERE LOWER(email) = LOWER(NEW.member_email);
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  _referral_code TEXT;
BEGIN
  -- Generate a unique referral code
  _referral_code := 'SS' || UPPER(SUBSTR(REPLACE(gen_random_uuid()::text, '-', ''), 1, 8));

  -- Create profile
  INSERT INTO public.profiles (id, email, full_name, avatar_url, referral_code)
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data ->> 'full_name', NEW.raw_user_meta_data ->> 'name', ''),
    COALESCE(NEW.raw_user_meta_data ->> 'avatar_url', NEW.raw_user_meta_data ->> 'picture', ''),
    _referral_code
  );

  -- Create wallet
  INSERT INTO public.wallets (user_id, currency)
  VALUES (NEW.id, 'USD');

  -- Create default preferences
  INSERT INTO public.user_preferences (user_id)
  VALUES (NEW.id);

  -- Create default push notification channel
  INSERT INTO public.notification_channels (user_id, channel_type, is_enabled)
  VALUES (NEW.id, 'push', TRUE);

  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."is_user_suspended"() RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN COALESCE((auth.jwt() -> 'app_metadata' ->> 'is_suspended')::boolean, false);
END;
$$;

CREATE OR REPLACE FUNCTION "public"."resolve_pending_household_invites"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE public.household_members
  SET member_id = NEW.id
  WHERE LOWER(member_email) = LOWER(NEW.email);
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."schedule_delayed_notification"("p_user_id" "uuid", "p_category" "text", "p_title" "text", "p_body" "text", "p_delay_minutes" integer) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_run_time TIMESTAMPTZ;
  v_cron_expr TEXT;
  v_job_name TEXT;
  v_job_id BIGINT;
BEGIN
  -- 1. Calculate future timestamp in UTC (Supabase operates in UTC)
  v_run_time := (NOW() AT TIME ZONE 'UTC') + (p_delay_minutes || ' minutes')::INTERVAL;

  -- 2. Construct standard cron expression: 'min hour day month *'
  v_cron_expr := EXTRACT(MINUTE FROM v_run_time) || ' ' ||
                 EXTRACT(HOUR FROM v_run_time) || ' ' ||
                 EXTRACT(DAY FROM v_run_time) || ' ' ||
                 EXTRACT(MONTH FROM v_run_time) || ' *';

  -- 3. Create a unique job name
  v_job_name := 'delayed_alert_' || REPLACE(p_user_id::TEXT, '-', '_') || '_' || EXTRACT(EPOCH FROM NOW())::BIGINT;

  -- 4. Schedule the job in pg_cron
  v_job_id := cron.schedule(
    v_job_name,
    v_cron_expr,
    format(
      'INSERT INTO public.notifications (user_id, category, title, body, action_url, sim_line_id, delivered_via, is_read) ' ||
      'VALUES (%L, %L, %L, %L, %L, NULL, ARRAY[%L], false); ' ||
      'SELECT cron.unschedule(%L);',
      p_user_id,
      p_category,
      p_title,
      p_body,
      '/notifications',
      'push',
      v_job_name
    )
  );

  RETURN v_job_name;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."sync_power_user_claim"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF (TG_OP = 'INSERT' OR NEW.is_power_user IS DISTINCT FROM OLD.is_power_user) THEN
    UPDATE auth.users
    SET raw_app_meta_data = 
      COALESCE(raw_app_meta_data, '{}'::jsonb) || 
      jsonb_build_object('is_power_user', NEW.is_power_user)
    WHERE id = NEW.id;
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."sync_suspended_claim"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF (TG_OP = 'INSERT' OR NEW.is_suspended IS DISTINCT FROM OLD.is_suspended) THEN
    UPDATE auth.users
    SET raw_app_meta_data = 
      COALESCE(raw_app_meta_data, '{}'::jsonb) || 
      jsonb_build_object('is_suspended', NEW.is_suspended)
    WHERE id = NEW.id;
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."update_line_health"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  NEW.health_score := public.calculate_health_score(
    NEW.id,
    NEW.status,
    NEW.last_topup_at
  );
  NEW.updated_at := NOW();
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."update_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$;
